const CSV_QUOTE_FORM_HTML="<section class=\"box\" aria-label=\"Quick CSV quote\" style=\"border:1px solid #354460;background:#11182b;border-radius:14px;padding:20px;margin:24px 0\">\n<h2>Request your CSV cleanup quote</h2>\n<p>Tell us what you need. No account, payment or file upload is required to request a scope review.</p>\n<form id=\"csv-quote\">\n<label for=\"csv-name\">Your name</label><input id=\"csv-name\" name=\"name\" autocomplete=\"name\" maxlength=\"160\" required>\n<label for=\"csv-email\">Work email</label><input id=\"csv-email\" name=\"email\" type=\"email\" autocomplete=\"email\" maxlength=\"254\" required>\n<label for=\"csv-company\">Company or business (write Individual if none)</label><input id=\"csv-company\" name=\"company\" maxlength=\"160\" required>\n<label for=\"csv-rows\">Approximate number of rows</label><input id=\"csv-rows\" name=\"rows\" type=\"number\" min=\"1\" max=\"1000000\" required>\n<label for=\"csv-details\">What needs cleaning, and which CSV columns or import template do you have?</label><textarea id=\"csv-details\" name=\"details\" minlength=\"15\" maxlength=\"4000\" rows=\"4\" required></textarea>\n<button type=\"submit\">Request a free scope review</button><p id=\"csv-quote-status\" role=\"status\" aria-live=\"polite\" style=\"color:#9fe6b8\"></p>\n</form><p style=\"font-size:13px;color:#b9c0d4\">Do not paste private client data, passwords or payment information into this form. A quote is not a contract or payment request.</p>\n<style>#csv-quote label{display:block;margin:14px 0 5px}#csv-quote input,#csv-quote textarea{box-sizing:border-box;width:100%;padding:12px;background:#0b1020;border:1px solid #596985;color:white;border-radius:8px;font:inherit}#csv-quote button{padding:13px 18px;margin-top:18px;background:#9fe6b8;color:#091b11;font-weight:700;border:0;border-radius:9px;cursor:pointer}#csv-quote button:disabled{opacity:.6}#csv-quote :focus-visible{outline:3px solid #9fe6b8;outline-offset:3px}</style>\n<script>\n(()=>{const form=document.getElementById('csv-quote'),status=document.getElementById('csv-quote-status'),button=form.querySelector('button');\nform.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;\nconst data={name:form.elements.namedItem('name').value.trim(),email:form.elements.namedItem('email').value.trim(),company:form.elements.namedItem('company').value.trim(),need:'CSV cleanup quote request. Rows: '+form.elements.namedItem('rows').value.trim()+'. Requirements: '+form.elements.namedItem('details').value.trim(),budget:'Exploring budget'};\nbutton.disabled=true;status.textContent='Submitting your scope request…';\ntry{const r=await fetch('/api/lead',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});const response=await r.json();if(!r.ok||response.ok!==true)throw new Error('Unable to save your request.');status.textContent='Request received. We will review your scope. No payment has been taken.';form.reset();}\ncatch{status.textContent='Submission could not be confirmed. Please try again later.';}finally{button.disabled=false;}\n});\n})();\n</script></section>";
