 updated=updated.replace(/<section class="hero">[\s\S]*?<\/section>/,TF_PREMIUM_HERO);
 updated=updated.replace(/<section class="grid">[\s\S]*?<\/section>/,TF_PREMIUM_SERVICES+TF_PREMIUM_PROCESS);
 updated=updated.replace('<section class="box" id="b2b"','<section class="box tf-b2b" id="b2b"');
